/** The raw VM words of one settlement script, or null when the id is unused. */
export function resultBytes(script: number): string | null {
  return TH08_RESULT_SCRIPTS[script]?.base64 ?? null;
}

/** How long one settlement script holds, in ANM ticks. */
export function resultLength(script: number): number {
  return TH08_RESULT_SCRIPTS[script]?.length ?? 0;
}

/** The atlas cell one settlement sprite id draws. */
export function resultCell(sprite: number): ResultCell | null {
  return TH08_RESULT_CELLS.find((c) => c.id === sprite) ?? null;
}
